import os
import json
import re

# Load any existing grids from session
def load_grids():
    d = os.environ.get('RLM_SESSION_DIR', '')
    if not d:
        return {}
    session_file = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
    try:
        text = open(session_file).read().replace('\\n', '\n')

        G = {}
        # Find demo pair markers
        for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', text):
            k, h, w = m[1], int(m[2]), int(m[3])
            lines = text[m.end():].split('\n')[:h]
            if k not in G and all(len(line) == w and all(x.isdigit() for x in line) for line in lines):
                G[k] = [[int(x) for x in line] for line in lines]
        return G
    except:
        return {}

G = load_grids()
print("Loaded grids:", sorted(G.keys()))

