def find_match(path, pattern):
    matches = []
    pattern_lower = pattern.lower()
    try:
        for root, dirs, files in os.walk(path):
            for f in files:
                if pattern_lower in f.lower():
                    matches.append(os.path.join(root, f))
        return matches
    except:
        return []

