def show_keys(obj, indent=0, max_depth=5):
    if isinstance(obj, dict):
        for k, v in obj.items():
            print("  " * indent + f"{k}")
            if indent < max_depth and (isinstance(v, (dict, list)) and not k.endswith('_id')):
                show_keys(v, indent + 1, max_depth)
    elif isinstance(obj, list):
        for i, item in enumerate(obj[:3]):  # Limit for safety
            print("  " * (indent + 1) + f"[{i}]")
            if isinstance(item, (dict, list)):
                show_keys(item, indent + 2, max_depth)

